package com.lbos.commercecustomer.controller; import com.lbos.commercecustomer.dto.request.*;import com.lbos.commercecustomer.dto.response.*;import com.lbos.commercecustomer.service.*;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import java.time.OffsetDateTime;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/checkout") public class CheckoutController {private final CheckoutService service;public CheckoutController(CheckoutService s){service=s;}private <T> ApiResponse<T> ok(HttpServletRequest r,String m,T d){return ApiResponse.of(Optional.ofNullable(r.getHeader("X-Correlation-Id")).orElse("not-provided"),m,d);}@PostMapping("/prepare") public ApiResponse<CheckoutResponse> prepare(@Valid @RequestBody CheckoutRequest r,HttpServletRequest h){return ok(h,"Checkout prepared",service.prepare(r));}
/** Called once, right after every retailer order from this checkout has actually been created - the only place a reward-points balance change is persisted (see CheckoutServiceImpl.confirm()). */
@PostMapping("/confirm") public ApiResponse<CheckoutResponse> confirm(@Valid @RequestBody CheckoutRequest r,HttpServletRequest h){return ok(h,"Checkout confirmed",service.confirm(r));}}